/**
 * What can go wrong. Arrives in Swift as a thrown `BusinessPreviewError`.
 */
public 
enum BusinessPreviewError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    /**
     * Not a pack the preview can read (no profile.json, not a zip).
     */
    case NotAPack(reason: String
    )
    /**
     * The profile breaks the schema's rules.
     */
    case Invalid(problems: [String]
    )
    case TooLarge(what: String, maxBytes: UInt64
    )
    case BadImage(path: String, reason: String
    )
    /**
     * A file doesn't match the hash the pack lists for it.
     */
    case HashMismatch(path: String
    )
    /**
     * Packs are fetched over https only.
     */
    case BadAddress(reason: String
    )
    case NotFound(id: String
    )
    /**
     * The copy on the phone has changed since it was imported.
     */
    case Damaged(id: String
    )
    case InUse
    case Corrupt(reason: String
    )
    case NewerData
    case Storage(reason: String
    )
    case Stopped(kind: ErrorKind
    )

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension BusinessPreviewError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeBusinessPreviewError: FfiConverterRustBuffer {
    typealias SwiftType = BusinessPreviewError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> BusinessPreviewError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .NotAPack(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 2: return .Invalid(
            problems: try FfiConverterSequenceString.read(from: &buf)
            )
        case 3: return .TooLarge(
            what: try FfiConverterString.read(from: &buf), 
            maxBytes: try FfiConverterUInt64.read(from: &buf)
            )
        case 4: return .BadImage(
            path: try FfiConverterString.read(from: &buf), 
            reason: try FfiConverterString.read(from: &buf)
            )
        case 5: return .HashMismatch(
            path: try FfiConverterString.read(from: &buf)
            )
        case 6: return .BadAddress(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 7: return .NotFound(
            id: try FfiConverterString.read(from: &buf)
            )
        case 8: return .Damaged(
            id: try FfiConverterString.read(from: &buf)
            )
        case 9: return .InUse
        case 10: return .Corrupt(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 11: return .NewerData
        case 12: return .Storage(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 13: return .Stopped(
            kind: try FfiConverterTypeErrorKind.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: BusinessPreviewError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .NotAPack(reason):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .Invalid(problems):
            writeInt(&buf, Int32(2))
            FfiConverterSequenceString.write(problems, into: &buf)
            
        
        case let .TooLarge(what,maxBytes):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(what, into: &buf)
            FfiConverterUInt64.write(maxBytes, into: &buf)
            
        
        case let .BadImage(path,reason):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(path, into: &buf)
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .HashMismatch(path):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(path, into: &buf)
            
        
        case let .BadAddress(reason):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .NotFound(id):
            writeInt(&buf, Int32(7))
            FfiConverterString.write(id, into: &buf)
            
        
        case let .Damaged(id):
            writeInt(&buf, Int32(8))
            FfiConverterString.write(id, into: &buf)
            
        
        case .InUse:
            writeInt(&buf, Int32(9))
        
        
        case let .Corrupt(reason):
            writeInt(&buf, Int32(10))
            FfiConverterString.write(reason, into: &buf)
            
        
        case .NewerData:
            writeInt(&buf, Int32(11))
        
        
        case let .Storage(reason):
            writeInt(&buf, Int32(12))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .Stopped(kind):
            writeInt(&buf, Int32(13))
            FfiConverterTypeErrorKind.write(kind, into: &buf)
            
        }
    }
}


