private enum InitializationResult {
    case ok
    case contractVersionMismatch
    case apiChecksumMismatch
}
// Use a global variable to perform the versioning checks. Swift ensures that
// the code inside is only computed once.
private let initializationResult: InitializationResult = {
    // Get the bindings contract version from our ComponentInterface
    let bindings_contract_version = 30
    // Get the scaffolding contract version by calling the into the dylib
    let scaffolding_contract_version = ffi_business_preview_core_uniffi_contract_version()
    if bindings_contract_version != scaffolding_contract_version {
        return InitializationResult.contractVersionMismatch
    }
    if (uniffi_business_preview_core_checksum_func_business_preview_concept_label() != 33806) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_business_preview_core_checksum_func_business_preview_error_kind() != 45471) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_business_preview_core_checksum_func_business_preview_pack_address() != 43583) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_business_preview_core_checksum_method_businesspreviewcore_background_time_expired() != 26763) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_business_preview_core_checksum_method_businesspreviewcore_background_work_pending() != 13073) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_business_preview_core_checksum_method_businesspreviewcore_business() != 48311) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_business_preview_core_checksum_method_businesspreviewcore_delete() != 62115) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_business_preview_core_checksum_method_businesspreviewcore_events() != 35854) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_business_preview_core_checksum_method_businesspreviewcore_import_pack() != 2668) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_business_preview_core_checksum_method_businesspreviewcore_launch_report() != 65465) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_business_preview_core_checksum_method_businesspreviewcore_phase() != 42052) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_business_preview_core_checksum_method_businesspreviewcore_prospects() != 34533) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_business_preview_core_checksum_method_businesspreviewcore_revision() != 36901) {
        return InitializationResult.apiChecksumMismatch
